/**
 * 紧凑版 Element Plus 图标（自动生成，勿手改）。
 *
 * 优化点：
 * 1. 去掉每个图标独立的 defineComponent / name / __name / setup 包装，
 *    改用共享工厂 ic()，每图标仅存 path 数据。
 * 2. path 坐标四舍五入到整数（viewBox 1024，误差 0.05%，肉眼不可感知），
 *    再省约 24% 的 path 数据体积。
 * 3. 移除数字与命令字母之间的多余空格（SVG path 语法允许）。
 * 通过 vite.config.ts 的 resolve.alias 把 "@element-plus/icons-vue"
 * 重定向到此模块。
 */
import { h, type Component } from 'vue'

const SVG_ATTRS = { xmlns: 'http://www.w3.org/2000/svg', viewBox: '0 0 1024 1024' }

/** 图标工厂：path 为字符串或字符串数组（多 path 图标） */
function ic(d: string | string[]): Component {
  const arr = Array.isArray(d) ? d : [d]
  return {
    setup() {
      return () => h('svg', SVG_ATTRS, arr.map((p) => h('path', { fill: 'currentColor', d: p })))
    },
  }
}

